        function getCategoryLabel(category) {
            const labels = {
                design: 'Design',
                development: 'Desenvolvimento',
                marketing: 'Marketing',
                writing: 'Redação',
                translation: 'Tradução',
                video: 'Vídeo/Áudio',
                other: 'Outros'
            };
            return labels[category] || category;
